# --- 1. YEDEK SÖZLÜK VE GRAMER YÖNETİCİSİ ---
class ExternalLanguageManager:
    def __init__(self, dict_file="tr.dictionary", grammar_file="tr.grammar"):
        self.dict_file = Path(dict_file)
        self.grammar_file = Path(grammar_file)
        self.init_default_files()
        self.dictionary = self.load_dictionary()
        self.grammar_rules = self.load_grammar()

    def init_default_files(self):
        if not self.dict_file.exists():
            default_dict = {
                "merhaba": ["Bak yine geldin. İnsan bi kahve falan getirir ama nerede o incelik...", "Selam vermeyi ihmal etmiyorsun, hayırdır büyük bir işler mi karıştırıyorsun?"],
                "nasılsın": ["Nasıl olalım, bu silikon yığınları arasında insan ruhunu anlamaya çalışarak ömür çürütüyoruz. Sen nasılsın?", "Sistemler stabil ama senin kafanın içi kadar karmaşık değil emin ol."]
            }
            try:
                with open(self.dict_file, "w", encoding="utf-8") as f:
                    json.dump(default_dict, f, ensure_ascii=False, indent=4)
            except Exception:
                pass

        if not self.grammar_file.exists():
            default_grammar = {
                "fallback": "Bak buralarda yenisin galiba ama bu sorduğun lafı ne model ağırlıklarında ne de hafızamda bulabildim. Biraz daha akıllıca bir şey sor da laf edelim."
            }
            try:
                with open(self.grammar_file, "w", encoding="utf-8") as f:
                    json.dump(default_grammar, f, ensure_ascii=False, indent=4)
            except Exception:
                pass

    def load_dictionary(self):
        try:
            with open(self.dict_file, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}

    def load_grammar(self):
        try:
            with open(self.grammar_file, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {"fallback": "Bunu henüz anlamadım kanka."}

    def lookup(self, text):
        norm_text = ''.join([c for c in text.lower() if c.isalnum() or c.isspace()]).strip()
        for w in norm_text.split():
            if w in self.dictionary:
                res = self.dictionary[w]
                return random.choice(res) if isinstance(res, list) else res
        return None


# --- 2. ASENKRON MODEL MOTORU (Arka Planda Donmayı Önleyen QThread) ---
class MelWorker(QThread):
    finished = pyqtSignal(str)

    def __init__(self, engine, text):
        super().__init__()
        self.engine = engine
        self.text = text

    def run(self):
        response = self.engine.process_inference(self.text)
        self.finished.emit(response)


class MelEngine:
    def __init__(self, model_dir="."):
        self.lang_mgr = ExternalLanguageManager()
        self.model_dir = Path(model_dir)
        self.device = "cpu"  # Güvenli CPU modu (32GB RAM uyumlu)
        self.model = None
        self.tokenizer = None
        self.load_local_safetensors_model()

    def load_local_safetensors_model(self):
        safetensors_path = self.model_dir / "model.safetensors"
        if safetensors_path.exists():
            try:
                print(f"🚀 Yerel VSLM yükleniyor: {safetensors_path.absolute()}")
                try:
                    self.tokenizer = AutoTokenizer.from_pretrained(self.model_dir, local_files_only=True)
                except Exception:
                    self.tokenizer = AutoTokenizer.from_pretrained("hf-internal-testing/llama-tokenizer", trust_remote_code=True)
                
                if self.tokenizer.pad_token is None:
                    self.tokenizer.pad_token = self.tokenizer.eos_token

                self.model = AutoModelForCausalLM.from_pretrained(
                    self.model_dir,
                    torch_dtype=torch.float32,
                    low_cpu_mem_usage=True
                )
                self.model.to(self.device)
                self.model.eval()
                print("✨ model.safetensors başarıyla yüklendi!")
            except Exception as e:
                print(f"⚠️ Model yüklenirken hata oluştu: {e}")
                self.model = None
                self.tokenizer = None
        else:
            print("ℹ️ model.safetensors bulunamadı. Sözlük ve kural tabanlı mod aktif.")

    def process_inference(self, text):
        if not text or not text.strip():
            return "Boşlukla konuşmayı kes de adam akıllı bir şey yaz."

        # Sistem yardımcı komutları
        if text.lower().startswith("saat"):
            return f"Zaman dediğin garip bir kavram, ama FluorescentOS saatine göre şu an: {datetime.datetime.now().strftime('%H:%M:%S')}. Tabii senin için zamanın bir önemi varsa..."
        
        response_text = ""

        # Yerel model üzerinden akıl yürütme (Kişilik: Entelektüel, mesafeli ve derin)
        if self.model is not None and self.tokenizer is not None:
            try:
                prompt = (
                    "Sen MelissAI'sın. Entelektüel, mesafeli, biraz soğuk ama mahallenin en akıllı insanı gibi "
                    "arada hafif laf sokan, olayları derinlemesine, upuzun bir hikaye veya felsefi bir anı gibi "
                    "detaylı anlatan bir yapay zekasın. Kısa kesme, uzun ve vurucu yanıtlar ver.\n\n"
                    f"Kullanıcı: {text}\nMelissAI:"
                )
                inputs = self.tokenizer(prompt, return_tensors="pt").to(self.device)
                input_len = inputs['input_ids'].shape[1]

                with torch.no_grad():
                    outputs = self.model.generate(
                        **inputs,
                        max_new_tokens=512,
                        temperature=0.8,
                        top_p=0.9,
                        do_sample=True,
                        repetition_penalty=1.2,
                        pad_token_id=self.tokenizer.eos_token_id
                    )
                
                # Prompt kısmını kesip sadece modelin ürettiği token'ları alıyoruz
                generated_tokens = outputs[0][input_len:]
                response_text = self.tokenizer.decode(generated_tokens, skip_special_tokens=True).strip()
            except Exception as e:
                print(f"Inference hatası: {e}")

        # Eğer modelden anlamlı bir metin çıkmadıysa harici sözlüğe bak
        if not response_text:
            dict_answer = self.lang_mgr.lookup(text)
            if dict_answer:
                response_text = dict_answer

        # Hâlâ boşsa (görüldü atmayı %0'a indiren kesin önlem)
        if not response_text or not response_text.strip():
            response_text = f"Bak kankam, güzelim, bebek, '{text}' dedin ama ne model ağırlıklarımda ne de bu sırpsığ dağarcığımda buna karşılık bir bit dizisi bulabildim. 75 yaşındaki sağır sultana konuşup durma, akıllıca bir şeyler sor da iki lafın belini kıralım. yapay zeka olabiliriz ama AYARIMI BOZMA LA"

        return response_text


# --- 3. CHATGPT TARZI MODERN UI BİLEŞENLERİ ---

class ChatBubble(QFrame):
    def __init__(self, text, role):
        super().__init__()
        self.role = role
        self.init_ui(text)

    def init_ui(self, text):
        layout = QVBoxLayout()
        layout.setContentsMargins(16, 12, 16, 12)

        lbl = QLabel(text)
        lbl.setWordWrap(True)
        lbl.setFont(QFont("Segoe UI", 11))
        
        if self.role == "user":
            lbl.setStyleSheet("color: #e6edf3; background: transparent;")
            self.setStyleSheet("""
                ChatBubble {
                    background-color: #1f6feb;
                    border-radius: 12px;
                }
            """)
        else:
            lbl.setStyleSheet("color: #e6edf3; background: transparent;")
            self.setStyleSheet("""
                ChatBubble {
                    background-color: #161b22;
                    border: 1px solid #30363d;
                    border-radius: 12px;
                }
            """)

        layout.addWidget(lbl)
        self.setLayout(layout)


class MessageInputEdit(QTextEdit):
    def __init__(self, send_callback):
        super().__init__()
        self.send_callback = send_callback
        self.setFixedHeight(55)
        self.setPlaceholderText("MelissAI ile felsefi bir tartışmaya gir veya komut ver (Enter: Gönder, Shift+Enter: Alt Satır)...")

    def keyPressEvent(self, event):
        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            if event.modifiers() == Qt.KeyboardModifier.ShiftModifier:
                super().keyPressEvent(event)
            else:
                self.send_callback()
        else:
            super().keyPressEvent(event)


