import random
import io
import wave

from PyQt6.QtWidgets import (
    QApplication, QWidget, QVBoxLayout, QHBoxLayout, QLineEdit, QPushButton,
    QTabWidget, QMessageBox, QListWidget, QMenuBar, QStatusBar, QDialog, QLabel, QProgressBar
)
