def generate_dialup_modem_sound(sample_rate=8000, duration_sec=30):
    """Harici dosyaya gerek kalmadan otantik dial-up modem sesleri üretir."""
    num_samples = sample_rate * duration_sec
    buffer_list = []
    
    for i in range(num_samples):
        t = i / sample_rate
        val = 0.0
        
        if t < 4.0:
            sub_t = t % 1.0
            if sub_t < 0.3:
                val = (math.sin(2 * math.pi * 697 * t) + math.sin(2 * math.pi * 1209 * t)) * 0.2
            elif 0.35 < sub_t < 0.45:
                val = (random.random() * 2 - 1) * 0.3
            else:
                val = 0.0
        elif t < 9.0:
            val = math.sin(2 * math.pi * 2100 * t + 0.5 * math.sin(2 * math.pi * 15 * t)) * 0.35
        elif t < 24.0:
            phase_mod = int(t * 8) % 4
            if phase_mod == 0:
                val = math.sin(2 * math.pi * 2400 * t) * 0.4
            elif phase_mod == 1:
                val = math.sin(2 * math.pi * 1200 * t) * 0.4
            elif phase_mod == 2:
                sweep_freq = 1000 + (t * 600) % 2200
                val = math.sin(2 * math.pi * sweep_freq * t) * 0.45
            else:
                val = (random.random() * 2 - 1) * 0.55
        else:
            if t > 28.5:
                chime_t = t - 28.5
                freq = 880 + chime_t * 900
                val = math.sin(2 * math.pi * freq * t) * 0.3 * max(0, (30.0 - t) / 1.5)
            else:
                val = math.sin(2 * math.pi * 1800 * t) * 0.25 + (random.random() * 2 - 1) * 0.04
                
        sample_int = int(max(-1.0, min(1.0, val)) * 32767)
        buffer_list.append(struct.pack('<h', sample_int))
        
    pcm_data = b''.join(buffer_list)
    
    wav_io = io.BytesIO()
    with wave.open(wav_io, 'wb') as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(pcm_data)
    wav_io.seek(0)
    return wav_io.read()


class NorthcellDialingDialog(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("FluorescentOS // Northcell Network Gateway")
        self.setFixedSize(460, 290)
        self.setWindowFlags(Qt.WindowType.CustomizeWindowHint | Qt.WindowType.WindowTitleHint)
        
        self.setStyleSheet("""
            QDialog {
                background-color: #0f1115;
                color: #00ffcc;
                font-family: 'Segoe UI', monospace;
                border-radius: 10px;
                border: 1px solid #00ffcc;
            }
            QLabel {
                color: #00ffcc;
                font-size: 13px;
            }
            QProgressBar {
                background-color: #1a1d24;
                border: 1px solid #005544;
                border-radius: 4px;
                text-align: center;
                color: #ffffff;
                font-weight: bold;
                font-size: 11px;
            }
            QProgressBar::chunk {
                background-color: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #00aa88, stop:1 #00ffcc);
                border-radius: 3px;
            }
        """)
        
        layout = QVBoxLayout(self)
        layout.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.setSpacing(10)
        
        self.header_label = QLabel("⚡ NORTHCELL PROTOCOL V90.4 - SECURE LINK")
        self.header_label.setStyleSheet("font-size: 11px; color: #008866; font-weight: bold; letter-spacing: 1px;")
        layout.addWidget(self.header_label, alignment=Qt.AlignmentFlag.AlignCenter)
        
        self.number_label = QLabel("📞 Aranan Hat: 0522 722 22 22")
        self.number_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.number_label.setStyleSheet("font-size: 14px; font-weight: bold; color: #00bbff; background-color: #141820; padding: 6px; border-radius: 6px; border: 1px solid #1f2633;")
        layout.addWidget(self.number_label)
        
        self.status_label = QLabel("Modem initialized. Dialing 0522 722 22 22...")
        self.status_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(self.status_label)
        
        self.freq_label = QLabel("697 / 1209 Hz (DTMF)")
        self.freq_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.freq_label.setStyleSheet("font-size: 22px; font-weight: bold; color: #ffaa00; letter-spacing: 2px;")
        layout.addWidget(self.freq_label)
        
        self.sub_label = QLabel("Aşama 1/4: Çevir sesi ve DTMF tuşlama sinyalleri...")
        self.sub_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.sub_label.setStyleSheet("font-size: 11px; color: #778899;")
        layout.addWidget(self.sub_label)
        
        self.progress_bar = QProgressBar()
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.setFixedHeight(18)
        layout.addWidget(self.progress_bar)
        
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.update_connection_progress)
        self.counter = 0
        self.total_steps = 150
        self.timer.start(200)
        
        self.connected = False

    def update_connection_progress(self):
        self.counter += 1
        progress_val = int((self.counter / self.total_steps) * 100)
        self.progress_bar.setValue(progress_val)
        
        if self.counter == 30:
            self.status_label.setText("Carrier Detected on 0522 722 22 22.")
            self.sub_label.setText("Aşama 2/4: Karşı tarafın cevap tonu bekleniyor...")
            self.freq_label.setText("2100 Hz (Tone)")
            self.freq_label.setStyleSheet("font-size: 22px; font-weight: bold; color: #00bbff; letter-spacing: 2px;")
        elif self.counter == 75:
            self.status_label.setText("Handshake / V.90 Negotiation...")
            self.sub_label.setText("Aşama 3/4: 0522 722 22 22 ile el sıkışılıyor (Bip-bop)...")
            self.freq_label.setText("2400 / 1200 Hz")
            self.freq_label.setStyleSheet("font-size: 22px; font-weight: bold; color: #ff00ff; letter-spacing: 2px;")
        elif self.counter == 120:
            self.status_label.setText("Authenticating Northcell Node...")
            self.sub_label.setText("Aşama 4/4: Güvenli tünel anahtarı doğrulanıyor...")
            self.freq_label.setText("1800 Hz (Carrier)")
            self.freq_label.setStyleSheet("font-size: 22px; font-weight: bold; color: #ffaa00; letter-spacing: 2px;")
            
        if self.counter >= self.total_steps:
            self.timer.stop()
            self.freq_label.setText("446.0 MHz (ONLINE)")
            self.freq_label.setStyleSheet("font-size: 22px; font-weight: bold; color: #00ff00; letter-spacing: 2px;")
            self.status_label.setText("CONNECTED TO 0533 098 1080!")
            self.status_label.setStyleSheet("color: #00ff00; font-weight: bold; font-size: 13px;")
            self.sub_label.setText("Northcell ağ geçidi tüneli aktif.")
            self.connected = True
            QTimer.singleShot(1500, self.accept)


