class AppManager:
    def __init__(self):
        self.opened_apps = {}

    def open_app(self, name, widget_class, workspace):
        if name in self.opened_apps:
            workspace.setCurrentWidget(self.opened_apps[name])
        else:
            app_instance = widget_class()
            workspace.addWidget(app_instance)
            self.opened_apps[name] = app_instance
            workspace.setCurrentWidget(app_instance)

    def close_app(self, name, workspace):
        if name in self.opened_apps:
            widget = self.opened_apps.pop(name)
            workspace.removeWidget(widget)
            widget.deleteLater()

    def switch_app(self, name, workspace):
        if name in self.opened_apps:
            workspace.setCurrentWidget(self.opened_apps[name])

    def list_apps(self):
        return list(self.opened_apps.keys())

class ScriptSandbox(QWidget):
    def __init__(self, name, code_str):
        super().__init__()
        layout = QVBoxLayout()
        self.setLayout(layout)
        
        info_lbl = QLabel(f"Çalıştırılan Harici Modül: {name}")
        info_lbl.setStyleSheet("font-weight: bold; color: #00F0FF; font-size: 14px;")
        layout.addWidget(info_lbl)
        
        self.exec_container = QVBoxLayout()
        layout.addLayout(self.exec_container)
        
        self.run_sandboxed_code(code_str, name)

    def run_sandboxed_code(self, code_str, name):
        try:
            local_scope = {}
            exec(code_str, {"__builtins__": __builtins__, "PyQt6": sys.modules.get("PyQt6")}, local_scope)
            
            ui_component = None
            for item_name, item in local_scope.items():
                if isinstance(item, type) and issubclass(item, (QWidget,)) and item not in (QWidget,):
                    ui_component = item()
                    break
            
            if ui_component:
                self.exec_container.addWidget(ui_component)
            else:
                fallback_lbl = QLabel("Kod başarıyla çalıştırıldı ancak görüntülenecek bir arayüz bileşeni (Widget) bulunamadı.")
                fallback_lbl.setStyleSheet("color: #8B949E;")
                self.exec_container.addWidget(fallback_lbl)
        except Exception as e:
            err_lbl = QLabel(f"Çalıştırma Hatası: {e}")
            err_lbl.setStyleSheet("color: #F85149;")
            self.exec_container.addWidget(err_lbl)

class AppRunner(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("AppRunner")
        self.resize(500, 400)

        layout = QVBoxLayout()
        self.status = QLabel("🔄 Scanning DownloadedAppsStuff...")
        layout.addWidget(self.status)

        self.app_list = QListWidget()
        layout.addWidget(self.app_list)

        self.run_btn = QPushButton("▶️ Run Selected App")
        self.run_btn.clicked.connect(self.run_app)
        layout.addWidget(self.run_btn)

        self.remove_btn = QPushButton("🗑️ Remove Selected App")
        self.remove_btn.clicked.connect(self.remove_app)
        layout.addWidget(self.remove_btn)

        self.refresh_btn = QPushButton("🔄 Refresh List")
        self.refresh_btn.clicked.connect(self.load_local_apps)
        layout.addWidget(self.refresh_btn)

        self.setLayout(layout)
        self.load_local_apps()

    def load_local_apps(self):
        self.app_list.clear()
        if os.path.exists(DOWNLOAD_DIR):
            files = os.listdir(DOWNLOAD_DIR)
            pyapps = [f for f in files if f.endswith(".PyApp")]
            if pyapps:
                self.status.setText("✅ Apps Found")
                for app in pyapps:
                    self.app_list.addItem(app)
            else:
                self.status.setText("❌ No Apps Found")
        else:
            self.status.setText("⚠️ 404 DownloadedAppsStuff Missing")

    def run_app(self):
        selected = self.app_list.currentItem()
        if selected:
            app_name = selected.text()
            path = os.path.join(DOWNLOAD_DIR, app_name)
            try:
                subprocess.Popen(["python", path])
                QMessageBox.information(self, "Run", f"{app_name} is running!")
            except Exception as e:
                QMessageBox.warning(self, "Error", f"Failed to run {app_name}: {e}")

    def remove_app(self):
        selected = self.app_list.currentItem()
        if selected:
            app_name = selected.text()
            path = os.path.join(DOWNLOAD_DIR, app_name)
            try:
                os.remove(path)
                QMessageBox.information(self, "Remove", f"{app_name} removed successfully!")
                self.load_local_apps()
            except Exception as e:
                QMessageBox.warning(self, "Error", f"Failed to remove {app_name}: {e}")

class BootScreen(QWidget):
    def __init__(self, on_finish):
        super().__init__()
        self.on_finish = on_finish
        self.val = 0

        layout = QVBoxLayout()
        layout.setAlignment(Qt.AlignmentFlag.AlignCenter)

        logo = QLabel("[/]")
        logo.setObjectName("BootLogo")
        logo.setAlignment(Qt.AlignmentFlag.AlignCenter)

        sub_text = QLabel("SPM")
        sub_text.setObjectName("BootSubText")
        sub_text.setAlignment(Qt.AlignmentFlag.AlignCenter)

        self.status_lbl = QLabel("Çekirdek yükleniyor...")
        self.status_lbl.setObjectName("BootStatus")
        self.status_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)

        self.progress = QProgressBar()
        self.progress.setObjectName("BootProgress")
        self.progress.setFixedWidth(280)
        self.progress.setTextVisible(False)
        self.progress.setRange(0, 100)

        layout.addWidget(logo)
        layout.addWidget(sub_text)
        layout.addSpacing(40)
        layout.addWidget(self.status_lbl)
        layout.addSpacing(8)
        layout.addWidget(self.progress, alignment=Qt.AlignmentFlag.AlignCenter)
        self.setLayout(layout)

        self.timer = QTimer()
        self.timer.timeout.connect(self.step)
        # 27.88 saniye (27880 milisaniye) / 100 adım = 278.8 ms per tick
        self.timer.start(279)

    def step(self):
        self.val += 1
        self.progress.setValue(self.val)

        if self.val <= 30:
            self.status_lbl.setText("Çekirdek (ANOE v6) başlatılıyor...")
        elif 31 <= self.val <= 60:
            self.status_lbl.setText("Gelişmiş PyQt6 grafik alt sistemi yükleniyor...")
        elif 61 <= self.val <= 90:
            self.status_lbl.setText("Kullanıcı profilleri ve servisler hazırlanıyor...")
        elif self.val >= 100:
            self.status_lbl.setText("Sistem Hazır")
            self.timer.stop()
            QTimer.singleShot(300, self.on_finish)

