# ================================================================
# FLOURESCENTOS 7 — COMPLETE SAVE STATE ENGINE
# ================================================================
FLOU_SAVESTATE_DIR = os.path.join(os.path.expanduser("~"), ".flourescentos7", "savestate")
os.makedirs(FLOU_SAVESTATE_DIR, exist_ok=True)
FLOU_SAVESTATE_FILE = os.path.join(FLOU_SAVESTATE_DIR, "system_state.json")
FLOU_SAVESTATE_BACKUP = os.path.join(FLOU_SAVESTATE_DIR, "system_state.bak.json")

class FlouSaveState:
    """Application/session-wide persistent state engine.
    Stores window geometry, open applications, generic Qt control values,
    app-specific save_state() payloads, desktop selection and feature data.
    """
    VERSION = 2

    def __init__(self, filename=FLOU_SAVESTATE_FILE):
        self.filename = filename
        self.backup = FLOU_SAVESTATE_BACKUP
        self.autosave_enabled = True
        self.last_state = {}

    def _json_safe(self, value):
        if value is None or isinstance(value, (str, int, float, bool)):
            return value
        if isinstance(value, (list, tuple)):
            return [self._json_safe(x) for x in value]
        if isinstance(value, dict):
            return {str(k): self._json_safe(v) for k, v in value.items()}
        try:
            return str(value)
        except Exception:
            return repr(value)

    def _widget_state(self, widget):
        state = {
            "class": widget.__class__.__name__,
            "object_name": widget.objectName(),
            "enabled": widget.isEnabled(),
            "visible": widget.isVisible(),
            "geometry": [widget.x(), widget.y(), widget.width(), widget.height()],
        }
        try:
            if isinstance(widget, QLineEdit):
                state["text"] = widget.text()
            elif isinstance(widget, QTextEdit):
                state["plain_text"] = widget.toPlainText()
            elif isinstance(widget, QPlainTextEdit):
                state["plain_text"] = widget.toPlainText()
            elif isinstance(widget, QComboBox):
                state["current_index"] = widget.currentIndex()
                state["current_text"] = widget.currentText()
            elif isinstance(widget, QCheckBox):
                state["checked"] = widget.isChecked()
            elif isinstance(widget, QRadioButton):
                state["checked"] = widget.isChecked()
            elif isinstance(widget, QSpinBox):
                state["value"] = widget.value()
            elif isinstance(widget, QDoubleSpinBox):
                state["value"] = widget.value()
            elif isinstance(widget, QSlider):
                state["value"] = widget.value()
            elif isinstance(widget, QTabWidget):
                state["current_index"] = widget.currentIndex()
            elif isinstance(widget, QStackedWidget):
                state["current_index"] = widget.currentIndex()
            elif isinstance(widget, QListWidget):
                state["current_row"] = widget.currentRow()
                state["selected_rows"] = [x.row() for x in widget.selectedIndexes()]
            elif isinstance(widget, QTableWidget):
                state["current_row"] = widget.currentRow()
                state["current_column"] = widget.currentColumn()
            elif isinstance(widget, QCalendarWidget):
                state["date"] = widget.selectedDate().toString(Qt.DateFormat.ISODate)
        except Exception:
            pass
        return state

    def _capture_tree(self, root):
        states = {}
        try:
            widgets = [root] + root.findChildren(QWidget)
        except Exception:
            widgets = [root]
        for index, widget in enumerate(widgets):
            key = widget.objectName()
            if not key:
                key = f"{widget.__class__.__name__}#{index}"
            if key in states:
                key = f"{key}#{index}"
            states[key] = self._widget_state(widget)
        return states

    def _restore_tree(self, root, states):
        if not isinstance(states, dict):
            return
        widgets = [root] + root.findChildren(QWidget)
        by_name = {}
        by_class = {}
        for index, widget in enumerate(widgets):
            name = widget.objectName()
            if name:
                by_name.setdefault(name, widget)
            by_class.setdefault(widget.__class__.__name__, []).append(widget)
        used = set()
        for key, state in states.items():
            widget = by_name.get(state.get("object_name")) if state.get("object_name") else None
            if widget is None:
                cls = state.get("class")
                candidates = by_class.get(cls, [])
                widget = next((w for w in candidates if id(w) not in used), None)
            if widget is None:
                continue
            used.add(id(widget))
            try:
                g = state.get("geometry")
                if isinstance(g, list) and len(g) == 4:
                    widget.setGeometry(*[int(x) for x in g])
                if "enabled" in state:
                    widget.setEnabled(bool(state["enabled"]))
                if isinstance(widget, QLineEdit) and "text" in state:
                    widget.setText(str(state["text"]))
                elif isinstance(widget, (QTextEdit, QPlainTextEdit)) and "plain_text" in state:
                    widget.setPlainText(str(state["plain_text"]))
                elif isinstance(widget, QComboBox):
                    idx = int(state.get("current_index", -1))
                    if 0 <= idx < widget.count():
                        widget.setCurrentIndex(idx)
                elif isinstance(widget, (QCheckBox, QRadioButton)) and "checked" in state:
                    widget.setChecked(bool(state["checked"]))
                elif isinstance(widget, (QSpinBox, QDoubleSpinBox)) and "value" in state:
                    widget.setValue(state["value"])
                elif isinstance(widget, QSlider) and "value" in state:
                    widget.setValue(int(state["value"]))
                elif isinstance(widget, (QTabWidget, QStackedWidget)) and "current_index" in state:
                    idx = int(state["current_index"])
                    if 0 <= idx < widget.count():
                        widget.setCurrentIndex(idx)
                elif isinstance(widget, QListWidget):
                    row = int(state.get("current_row", -1))
                    if 0 <= row < widget.count():
                        widget.setCurrentRow(row)
                elif isinstance(widget, QTableWidget):
                    r = int(state.get("current_row", -1))
                    c = int(state.get("current_column", -1))
                    if r >= 0 and r < widget.rowCount() and c >= 0 and c < widget.columnCount():
                        widget.setCurrentCell(r, c)
                elif isinstance(widget, QCalendarWidget) and state.get("date"):
                    widget.setSelectedDate(QDate.fromString(state["date"], Qt.DateFormat.ISODate))
            except Exception:
                pass

    def capture(self, main_window, desktop):
        state = {
            "schema": "FlourescentOS.SaveState",
            "version": self.VERSION,
            "saved_at": time.time(),
            "saved_at_text": time.ctime(),
            "application": "FlourescentOS 7",
            "main_window": {
                "geometry": [main_window.x(), main_window.y(), main_window.width(), main_window.height()],
                "window_state": int(main_window.windowState()),
                "fullscreen": main_window.isFullScreen(),
                "maximized": main_window.isMaximized(),
                "minimized": main_window.isMinimized(),
            },
            "root_stack_index": desktop.main_window.root_stack.currentIndex(),
            "desktop": {
                "workspace_index": desktop.workspace.currentIndex(),
                "status_text": desktop.status_time_lbl.text(),
                "state_file": desktop.state_file,
            },
            "open_apps": [],
            "widgets": {},
        }
        for name, widget in list(desktop.app_manager.opened_apps.items()):
            entry = {
                "name": name,
                "class": widget.__class__.__name__,
                "window_title": widget.windowTitle(),
                "geometry": [widget.x(), widget.y(), widget.width(), widget.height()],
                "visible": widget.isVisible(),
                "custom_state": None,
                "widget_state": self._capture_tree(widget),
            }
            try:
                if hasattr(widget, "save_state") and callable(widget.save_state):
                    entry["custom_state"] = self._json_safe(widget.save_state())
            except Exception:
                entry["custom_state"] = None
            state["open_apps"].append(entry)
        try:
            state["feature_stores"] = {}
            feature_root = globals().get("FLOU_EXPANSION_DIR")
            if feature_root and os.path.isdir(feature_root):
                for name in os.listdir(feature_root):
                    path = os.path.join(feature_root, name)
                    if name.endswith(".json") and os.path.isfile(path):
                        try:
                            with open(path, "r", encoding="utf-8") as f:
                                state["feature_stores"][name] = json.load(f)
                        except Exception:
                            pass
        except Exception:
            state["feature_stores"] = {}
        return state

    def save(self, main_window, desktop):
        state = self.capture(main_window, desktop)
        os.makedirs(os.path.dirname(self.filename), exist_ok=True)
        if os.path.exists(self.filename):
            try:
                shutil.copy2(self.filename, self.backup)
            except Exception:
                pass
        temp = self.filename + ".tmp"
        with open(temp, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2, default=str)
        os.replace(temp, self.filename)
        self.last_state = state
        return self.filename

    def load(self):
        candidates = [self.filename, self.backup]
        for path in candidates:
            try:
                if os.path.exists(path):
                    with open(path, "r", encoding="utf-8") as f:
                        state = json.load(f)
                    if isinstance(state, dict) and state.get("schema") == "FlourescentOS.SaveState":
                        self.last_state = state
                        return state
            except Exception:
                continue
        return {}

    def restore_feature_stores(self, state):
        stores = state.get("feature_stores", {})
        root = globals().get("FLOU_EXPANSION_DIR")
        if not root:
            return
        os.makedirs(root, exist_ok=True)
        for name, data in stores.items():
            if not name.endswith(".json"):
                continue
            path = os.path.join(root, os.path.basename(name))
            try:
                tmp = path + ".savestate.tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(data, f, ensure_ascii=False, indent=2, default=str)
                os.replace(tmp, path)
            except Exception:
                pass

    def restore(self, main_window, desktop, apps_dict):
        state = self.load()
        if not state:
            return False
        try:
            self.restore_feature_stores(state)
            geometry = state.get("main_window", {}).get("geometry")
            if isinstance(geometry, list) and len(geometry) == 4:
                main_window.setGeometry(*[int(x) for x in geometry])
            window_state = int(state.get("main_window", {}).get("window_state", 0))
            if window_state:
                main_window.setWindowState(Qt.WindowState(window_state))
            for entry in state.get("open_apps", []):
                name = entry.get("name")
                if name not in apps_dict:
                    continue
                try:
                    desktop.app_manager.open_app(name, apps_dict[name], desktop.workspace)
                    widget = desktop.app_manager.opened_apps.get(name)
                    if widget is None:
                        continue
                    g = entry.get("geometry")
                    if isinstance(g, list) and len(g) == 4:
                        widget.setGeometry(*[int(x) for x in g])
                    if entry.get("custom_state") is not None and hasattr(widget, "load_state"):
                        try:
                            widget.load_state(entry["custom_state"])
                        except Exception:
                            pass
                    self._restore_tree(widget, entry.get("widget_state", {}))
                    widget.setVisible(bool(entry.get("visible", True)))
                except Exception:
                    continue
            idx = int(state.get("desktop", {}).get("workspace_index", -1))
            if 0 <= idx < desktop.workspace.count():
                desktop.workspace.setCurrentIndex(idx)
            root_idx = int(state.get("root_stack_index", 2))
            if 0 <= root_idx < desktop.main_window.root_stack.count():
                desktop.main_window.root_stack.setCurrentIndex(root_idx)
            return True
        except Exception:
            return False

    def delete(self):
        removed = False
        for path in (self.filename, self.backup):
            try:
                if os.path.exists(path):
                    os.remove(path)
                    removed = True
            except OSError:
                pass
        self.last_state = {}
        return removed

