import platform as _fl_platform
import socket as _fl_socket
import hashlib as _fl_hashlib
import zipfile as _fl_zipfile
import pathlib as _fl_pathlib
import subprocess as _fl_subprocess
import traceback as _fl_traceback
import datetime as _fl_datetime
import shutil as _fl_shutil
import fnmatch as _fl_fnmatch
from PyQt6.QtWidgets import QCheckBox, QSpinBox, QFormLayout, QGroupBox, QTableWidget, QTableWidgetItem, QRadioButton, QPlainTextEdit, QComboBox, QCalendarWidget, QSlider, QDoubleSpinBox

FLOU_EXPANSION_DIR = os.path.join(os.path.expanduser('~'), '.flourescentos7')
os.makedirs(FLOU_EXPANSION_DIR, exist_ok=True)

class FlouFeatureStore:
    """Thread-safe enough single-process persistent store for the feature center."""
    def __init__(self, name):
        self.name = name
        self.path = os.path.join(FLOU_EXPANSION_DIR, name + '.json')
        self.data = {}
        self.load()
    def load(self):
        try:
            if os.path.exists(self.path):
                with open(self.path, 'r', encoding='utf-8') as f: self.data = json.load(f)
        except Exception: self.data = {}
        return self.data
    def save(self):
        tmp=self.path+'.tmp'
        with open(tmp,'w',encoding='utf-8') as f: json.dump(self.data,f,ensure_ascii=False,indent=2,default=str)
        os.replace(tmp,self.path)
        return self.path
    def clear(self): self.data={}; return self.save()
    def set(self,key,value): self.data[key]=value; self.save(); return value
    def get(self,key,default=None): return self.data.get(key,default)
    def delete(self,key):
        existed=key in self.data
        self.data.pop(key,None); self.save(); return existed
    def keys(self): return list(self.data.keys())

class FlouFeatureBase(QWidget):
    feature_id='base'; feature_icon='🧩'; feature_title='Feature'
    def __init__(self,kernel=None):
        super().__init__(); self.kernel=kernel; self.store=FlouFeatureStore(self.feature_id)
        self.setWindowTitle(f'{self.feature_icon} {self.feature_title} - FlourescentOS 7')
        self.resize(900,620); self._build_ui()
    def _build_ui(self):
        root=QVBoxLayout(self); root.setContentsMargins(14,14,14,14); root.setSpacing(10)
        title=QLabel(f'{self.feature_icon} {self.feature_title}')
        title.setStyleSheet('font-size:22px;font-weight:700;padding:6px;')
        root.addWidget(title)
        self.info=QLabel(self.description()); self.info.setWordWrap(True); root.addWidget(self.info)
        self.table=QTableWidget(0,2); self.table.setHorizontalHeaderLabels(['Anahtar','Değer']); self.table.horizontalHeader().setStretchLastSection(True); root.addWidget(self.table,1)
        row=QHBoxLayout(); self.input=QLineEdit(); self.input.setPlaceholderText('İşlem için değer / ad / yol...'); row.addWidget(self.input,2)
        for label,method in self.actions():
            b=QPushButton(label); b.clicked.connect(method); row.addWidget(b)
        root.addLayout(row); self.refresh()
    def description(self): return 'FlourescentOS sistem özelliği. Veriler yerel özellik deposunda saklanır.'
    def actions(self): return [('Yenile',self.refresh)]
    def log(self,action,detail=''):
        try:
            if self.kernel and hasattr(self.kernel,'audit_manager'): self.kernel.audit_manager.record(action,detail or self.feature_title)
        except Exception: pass
    def notify(self,text): QMessageBox.information(self,self.feature_title,text)
    def error(self,text): QMessageBox.warning(self,self.feature_title,text)
    def refresh(self):
        self.table.setRowCount(0)
        for k,v in self.store.data.items():
            r=self.table.rowCount(); self.table.insertRow(r); self.table.setItem(r,0,QTableWidgetItem(str(k))); self.table.setItem(r,1,QTableWidgetItem(json.dumps(v,ensure_ascii=False) if isinstance(v,(dict,list)) else str(v)))
        self.info.setText(f'{self.description()}  |  {len(self.store.data)} kayıt')
    def value(self): return self.input.text().strip()

class FlouUserGroups(FlouFeatureBase):
    def add_user(self):
        n=self.value();
        if not n: return self.error('Kullanıcı adı boş olamaz.')
        users=self.store.get('users',[]);
        if n not in users: users.append(n); self.store.set('users',users); self.refresh(); self.log('User Add',n)
    def add_group(self):
        n=self.value();
        if not n: return self.error('Grup adı boş olamaz.')
        groups=self.store.get('groups',{}); groups.setdefault(n,[]); self.store.set('groups',groups); self.refresh(); self.log('Group Add',n)
    def join(self):
        parts=[x.strip() for x in self.value().split(':',1)];
        if len(parts)!=2: return self.error('Format: kullanıcı:grup')
        groups=self.store.get('groups',{}); groups.setdefault(parts[1],[]);
        if parts[0] not in groups[parts[1]]: groups[parts[1]].append(parts[0])
        self.store.set('groups',groups); self.refresh()
    def list_all(self): self.refresh(); self.notify(json.dumps(self.store.data,ensure_ascii=False,indent=2))
    def actions(self): return [('Yeni kullanıcı',self.add_user),('Yeni grup',self.add_group),('Gruba ekle',self.join),('Listele',self.list_all)]

class FlouPermissions(FlouFeatureBase):
    def read_perm(self):
        p=self.value();
        if not os.path.exists(p): return self.error('Yol bulunamadı.')
        st=os.stat(p); self.notify(f'Path: {p}\nMode: {oct(st.st_mode & 0o777)}\nOwner UID: {getattr(st,"st_uid", "-")}'); self.log('Permission Read',p)
    def chmod(self):
        p=self.value();
        if ':' not in p: return self.error('Format: yol:755')
        path,mode=p.rsplit(':',1);
        try: os.chmod(path,int(mode,8)); self.refresh(); self.log('Permission Change',p)
        except Exception as e: self.error(str(e))
    def owner(self):
        p=self.value();
        if os.path.exists(p): self.notify(f'UID: {getattr(os.stat(p),"st_uid","-")} / GID: {getattr(os.stat(p),"st_gid","-")}')
    def audit(self):
        p=self.value(); self.store.set('last_audit',{'path':p,'exists':os.path.exists(p),'time':str(_fl_datetime.datetime.now())}); self.refresh()
    def actions(self): return [('İzin oku',self.read_perm),('İzin değiştir',self.chmod),('Sahip',self.owner),('Denetle',self.audit)]

class FlouFileIndexer(FlouFeatureBase):
    def scan(self):
        root=self.value() or os.getcwd();
        if not os.path.isdir(root): return self.error('Klasör bulunamadı.')
        files=[]
        for base,dirs,names in os.walk(root):
            dirs[:]=[d for d in dirs if d not in {'.git','__pycache__','.venv'}]
            for n in names:
                p=os.path.join(base,n)
                try: st=os.stat(p); files.append({'path':p,'name':n,'size':st.st_size,'mtime':st.st_mtime,'ext':os.path.splitext(n)[1].lower()})
                except OSError: pass
            if len(files)>=5000: break
        self.store.set('files',files); self.refresh(); self.notify(f'{len(files)} dosya indekslendi.')
    def search_name(self):
        q=self.value().lower(); rows=[x for x in self.store.get('files',[]) if q in x['name'].lower()]; self.notify('\n'.join(x['path'] for x in rows[:100]) or 'Sonuç yok.')
    def search_ext(self):
        q=self.value().lower(); q=q if q.startswith('.') else '.'+q; rows=[x for x in self.store.get('files',[]) if x['ext']==q]; self.notify('\n'.join(x['path'] for x in rows[:100]) or 'Sonuç yok.')
    def save_index(self): self.store.save(); self.notify(f'İndeks kaydedildi: {self.store.path}')
    def actions(self): return [('Klasör tara',self.scan),('İsim ara',self.search_name),('Uzantı ara',self.search_ext),('İndeksi kaydet',self.save_index)]

class FlouTrash(FlouFeatureBase):
    def trash(self):
        p=self.value();
        if not os.path.exists(p): return self.error('Dosya/k klasör bulunamadı.')
        td=os.path.join(FLOU_EXPANSION_DIR,'trash'); os.makedirs(td,exist_ok=True); token=_fl_hashlib.sha256((p+str(time.time())).encode()).hexdigest()[:16]; dest=os.path.join(td,token+'_'+os.path.basename(p));
        _fl_shutil.move(p,dest); items=self.store.get('items',[]); items.append({'original':p,'trash':dest,'time':time.time()}); self.store.set('items',items); self.refresh()
    def restore(self):
        items=self.store.get('items',[]);
        if not items: return self.error('Çöp kutusu boş.')
        item=items[-1]; os.makedirs(os.path.dirname(item['original']) or '.',exist_ok=True); _fl_shutil.move(item['trash'],item['original']); items.pop(); self.store.set('items',items); self.refresh()
    def empty(self):
        for x in self.store.get('items',[]):
            try:
                if os.path.isdir(x['trash']): _fl_shutil.rmtree(x['trash'])
                else: os.remove(x['trash'])
            except OSError: pass
        self.store.set('items',[]); self.refresh()
    def list_items(self): self.refresh(); self.notify(json.dumps(self.store.get('items',[]),ensure_ascii=False,indent=2))
    def actions(self): return [('Sil',self.trash),('Geri yükle',self.restore),('Çöpü boşalt',self.empty),('Listele',self.list_items)]

class FlouArchive(FlouFeatureBase):
    def make_zip(self):
        p=self.value();
        if not os.path.exists(p): return self.error('Yol bulunamadı.')
        dest=p.rstrip('/\\')+'.zip';
        with _fl_zipfile.ZipFile(dest,'w',_fl_zipfile.ZIP_DEFLATED) as z:
            if os.path.isdir(p):
                for root,dirs,files in os.walk(p):
                    for f in files: z.write(os.path.join(root,f),os.path.relpath(os.path.join(root,f),os.path.dirname(p)))
            else: z.write(p,os.path.basename(p))
        self.notify(f'Oluşturuldu: {dest}'); self.refresh()
    def extract(self):
        p=self.value();
        if not _fl_zipfile.is_zipfile(p): return self.error('Geçerli ZIP değil.')
        dest=p[:-4]+'_extracted'; os.makedirs(dest,exist_ok=True);
        with _fl_zipfile.ZipFile(p) as z: z.extractall(dest)
        self.notify(f'Çıkarıldı: {dest}')
    def list_zip(self):
        p=self.value();
        if not _fl_zipfile.is_zipfile(p): return self.error('Geçerli ZIP değil.')
        with _fl_zipfile.ZipFile(p) as z: self.notify('\n'.join(z.namelist()[:300]))
    def sha(self):
        p=self.value();
        if not os.path.isfile(p): return self.error('Dosya yok.')
        h=_fl_hashlib.sha256();
        with open(p,'rb') as f:
            for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
        self.notify(h.hexdigest())
    def actions(self): return [('ZIP oluştur',self.make_zip),('ZIP çıkar',self.extract),('İçeriği listele',self.list_zip),('SHA256',self.sha)]

class FlouSnapshots(FlouFeatureBase):
    def snapshot(self):
        root=self.value() or os.getcwd();
        if not os.path.isdir(root): return self.error('Klasör bulunamadı.')
        entries=[]
        for base,dirs,files in os.walk(root):
            for f in files:
                p=os.path.join(base,f)
                try:
                    st=os.stat(p); entries.append({'path':os.path.relpath(p,root),'size':st.st_size,'mtime':st.st_mtime})
                except OSError: pass
        sid=_fl_datetime.datetime.now().strftime('%Y%m%d_%H%M%S'); snaps=self.store.get('snapshots',{}); snaps[sid]={'root':root,'entries':entries}; self.store.set('snapshots',snaps); self.refresh(); self.notify(f'Snapshot {sid}: {len(entries)} dosya')
    def list_snapshots(self): self.notify(json.dumps(self.store.get('snapshots',{}),ensure_ascii=False,indent=2))
    def compare(self):
        snaps=self.store.get('snapshots',{}); ids=list(snaps);
        if len(ids)<2: return self.error('Karşılaştırmak için en az iki snapshot gerekli.')
        a,b=snaps[ids[-2]],snaps[ids[-1]]; ma={x['path']:x for x in a['entries']}; mb={x['path']:x for x in b['entries']}; added=sorted(set(mb)-set(ma)); removed=sorted(set(ma)-set(mb)); changed=sorted(k for k in set(ma)&set(mb) if ma[k]['size']!=mb[k]['size'] or ma[k]['mtime']!=mb[k]['mtime']); self.notify(f'Eklenen: {len(added)}\nSilinen: {len(removed)}\nDeğişen: {len(changed)}')
    def delete_snapshot(self):
        n=self.value(); snaps=self.store.get('snapshots',{});
        if n in snaps: del snaps[n]; self.store.set('snapshots',snaps); self.refresh()
    def actions(self): return [('Snapshot al',self.snapshot),('Listele',self.list_snapshots),('Karşılaştır',self.compare),('Sil',self.delete_snapshot)]

