class FlouIntegrity(FlouFeatureBase):
    def manifest(self):
        root=self.value() or os.getcwd();
        if not os.path.isdir(root): return self.error('Klasör bulunamadı.')
        data={};
        for base,dirs,files in os.walk(root):
            for n in files:
                p=os.path.join(base,n); h=_fl_hashlib.sha256()
                try:
                    with open(p,'rb') as f:
                        for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
                    data[os.path.relpath(p,root)]=h.hexdigest()
                except OSError: pass
        self.store.set('root',root); self.store.set('manifest',data); self.refresh(); self.notify(f'{len(data)} dosya manifestlendi.')
    def verify(self):
        root=self.store.get('root'); old=self.store.get('manifest',{});
        if not root: return self.error('Manifest yok.')
        changed=[]
        for rel,want in old.items():
            p=os.path.join(root,rel);
            if not os.path.exists(p): changed.append('MISSING '+rel); continue
            h=_fl_hashlib.sha256();
            try:
                with open(p,'rb') as f:
                    for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
                if h.hexdigest()!=want: changed.append('CHANGED '+rel)
            except OSError: changed.append('UNREADABLE '+rel)
        self.notify('Temiz.' if not changed else '\n'.join(changed[:100]))
    def diff(self): self.verify()
    def delete(self): self.store.delete('manifest'); self.store.delete('root'); self.refresh()
    def actions(self): return [('Manifest oluştur',self.manifest),('Doğrula',self.verify),('Farkları bul',self.diff),('Manifest sil',self.delete)]

