class FlouFeatureCenter(QWidget):
    """Central launcher for the expanded FlourescentOS 7 feature set."""
    def __init__(self,kernel=None):
        super().__init__(); self.kernel=kernel; self.setWindowTitle('🧩 FlourescentOS 7 Feature Center'); self.resize(1100,700)
        root=QVBoxLayout(self); head=QHBoxLayout(); title=QLabel('🧩 FlourescentOS 7 — Feature Center'); title.setStyleSheet('font-size:24px;font-weight:700;'); head.addWidget(title); head.addStretch(); root.addLayout(head)
        self.search=QLineEdit(); self.search.setPlaceholderText('Özellik ara...'); self.search.textChanged.connect(self.filter); root.addWidget(self.search)
        self.list=QListWidget(); root.addWidget(self.list,1)
        self.status=QLabel('Hazır'); root.addWidget(self.status)
        self.registry={
            'Users & Groups': FlouUserGroups,
            'Permissions': FlouPermissions,
            'File Indexer': FlouFileIndexer,
            'Trash & Recovery': FlouTrash,
            'Archive Center': FlouArchive,
            'System Snapshots': FlouSnapshots,
            'Network Diagnostics': FlouNetworkDiag,
            'Firewall Rules': FlouFirewall,
            'DNS Cache': FlouDNSCache,
            'Clipboard History': FlouClipboard,
            'Recent Items': FlouRecent,
            'Virtual Workspaces': FlouWorkspaces,
            'Theme Manager': FlouThemes,
            'Hotkey Manager': FlouHotkeys,
            'Startup Manager': FlouStartup,
            'Service Center': FlouServices,
            'Hardware Center': FlouHardware,
            'Power Center': FlouPower,
            'Screenshot Center': FlouScreenshot,
            'Session Recorder': FlouRecorder,
            'System Health': FlouHealth,
            'Crash Reporter': FlouCrash,
            'Integrity Guard': FlouIntegrity,
            'Local Vault': FlouVault,
            'Developer Tools': FlouDeveloper,
            'Automation Center': FlouAutomation,
            'Accessibility Center': FlouAccessibility,
            'Privacy Center': FlouPrivacy,
            'Flou Help Center': FlouHelp,
        }
        self.list.itemDoubleClicked.connect(self.open_selected); self.populate()
    def populate(self):
        self.list.clear(); q=self.search.text().lower();
        for _,cid,title,desc in FLOU_FEATURE_CATALOG:
            if not q or q in title.lower() or q in desc.lower(): self.list.addItem(f'{dict(self.registry.items()).get(title).__name__ if title in self.registry else cid}  |  {title} — {desc}')
        self.status.setText(f'{self.list.count()} özellik gösteriliyor / toplam {len(FLOU_FEATURE_CATALOG)}')
    def filter(self,_): self.populate()
    def open_selected(self,item):
        text=item.text(); title=text.split('  |  ',1)[-1].split(' — ',1)[0]; cls=self.registry.get(title);
        if cls:
            w=cls(self.kernel); w.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose); w.show(); w.raise_(); w.activateWindow(); self.status.setText(f'Açıldı: {title}')

# Additional aliases make the feature center discoverable from existing launcher code.
FlourescentFeatureCenter = FlouFeatureCenter


class FlouSaveStateCenter(QWidget):
    """GUI for inspecting, saving, restoring and resetting the complete system savestate."""
    def __init__(self, kernel=None):
        super().__init__()
        self.kernel = kernel
        self.engine = FlouSaveState()
        self.setWindowTitle("💾 FlourescentOS 7 — Complete Save State")
        self.resize(900, 650)
        root = QVBoxLayout(self)
        title = QLabel("💾 Complete Save State")
        title.setStyleSheet("font-size:24px;font-weight:700;")
        root.addWidget(title)
        self.info = QLabel()
        self.info.setWordWrap(True)
        root.addWidget(self.info)
        self.preview = QPlainTextEdit()
        self.preview.setReadOnly(True)
        root.addWidget(self.preview, 1)
        row = QHBoxLayout()
        for label, fn in [
            ("Şimdi Kaydet", self.save_now),
            ("Durumu Yükle", self.load_now),
            ("Önizleme", self.preview_now),
            ("Savestate Sıfırla", self.reset_now),
        ]:
            b = QPushButton(label)
            b.clicked.connect(fn)
            row.addWidget(b)
        root.addLayout(row)
        self.refresh()

    def refresh(self):
        state = self.engine.load()
        if state:
            apps = [x.get("name") for x in state.get("open_apps", [])]
            self.info.setText(
                f"Durum: kayıtlı | Sürüm: {state.get('version')} | "
                f"Son kayıt: {state.get('saved_at_text','-')} | "
                f"Açık uygulama: {len(apps)}"
            )
            self.preview.setPlainText(json.dumps(state, ensure_ascii=False, indent=2, default=str)[:30000])
        else:
            self.info.setText("Durum: henüz savestate yok.")
            self.preview.clear()

    def save_now(self):
        if self.kernel and hasattr(self.kernel, "save_state"):
            path = self.kernel.save_state()
        else:
            path = self.engine.filename
        self.refresh()
        QMessageBox.information(self, "Savestate", f"Tam sistem durumu kaydedildi:\n{path}")

    def load_now(self):
        if self.kernel and hasattr(self.kernel, "load_state"):
            ok = self.kernel.load_state()
        else:
            ok = False
        self.refresh()
        QMessageBox.information(self, "Savestate", "Savestate yüklendi." if ok else "Yüklenecek geçerli savestate bulunamadı.")

    def preview_now(self):
        self.refresh()

    def reset_now(self):
        if QMessageBox.question(self, "Savestate", "Tüm kayıtlı sistem durumunu silmek istiyor musunuz?") == QMessageBox.StandardButton.Yes:
            self.engine.delete()
            self.refresh()

